#!/usr/bin/env node
/**
 * Fix SEO issues across ALL entity types (conditions, treatments, resources)
 *
 * This script:
 * 1. Removes obsolete schema_injection fields
 * 2. Fixes/removes incorrect canonical URLs (let code auto-generate)
 * 3. Adds seo.no_index = false where missing
 * 4. Cleans up auto-generated seo.title/description
 *
 * Usage:
 *   node scripts/fix-all-entities-seo.cjs
 *   node scripts/fix-all-entities-seo.cjs --dry-run  # Preview changes only
 */

const fs = require('fs');
const path = require('path');

const DRY_RUN = process.argv.includes('--dry-run');
const ENTITY_DIRS = [
  { path: 'data/conditions', type: 'condition', pathPrefix: '/conditions/' },
  { path: 'data/treatments', type: 'treatment', pathPrefix: '/treatments/' },
  { path: 'data/resources', type: 'resource', pathPrefix: '/resources/' },
];

let filesProcessed = 0;
let filesModified = 0;
let issues = [];
const stats = {
  schemaInjectionRemoved: 0,
  canonicalFixed: 0,
  canonicalRemoved: 0,
  noIndexAdded: 0,
  titleRemoved: 0,
  descriptionRemoved: 0,
};

/**
 * Fix a single JSON file
 */
function fixEntityFile(filePath, entityType, pathPrefix) {
  try {
    const content = fs.readFileSync(filePath, 'utf-8');
    const data = JSON.parse(content);

    let modified = false;
    const fileIssues = [];

    // 1. Remove schema_injection (obsolete - code auto-generates schema)
    if (data.schema_injection) {
      fileIssues.push('Removed schema_injection');
      delete data.schema_injection;
      stats.schemaInjectionRemoved++;
      modified = true;
    }

    // 2. Handle canonical URLs
    if (data.seo?.canonical) {
      const oldCanonical = data.seo.canonical;
      let shouldRemove = false;
      let shouldFix = false;
      let newCanonical = oldCanonical;

      // Check if it's a relative URL (starts with /)
      if (oldCanonical.startsWith('/')) {
        // Relative URLs should be removed - let code auto-generate
        shouldRemove = true;
        fileIssues.push(`Removed relative canonical: ${oldCanonical}`);
      } else {
        // Absolute URL - check if needs fixing

        // Fix wrong path (e.g., /treatment/ → /treatments/)
        if (entityType === 'treatment' && oldCanonical.includes('/treatment/') && !oldCanonical.includes('/treatments/')) {
          newCanonical = newCanonical.replace('/treatment/', '/treatments/');
          shouldFix = true;
          fileIssues.push('Fixed path: /treatment/ → /treatments/');
        }

        // Add www subdomain
        if (newCanonical.startsWith('https://heypsych.com')) {
          newCanonical = newCanonical.replace('https://heypsych.com', 'https://www.heypsych.com');
          shouldFix = true;
          fileIssues.push('Added www subdomain');
        }

        // Check if canonical matches expected pattern
        const expectedPattern = new RegExp(`^https://www\\.heypsych\\.com${pathPrefix}.+$`);
        if (!expectedPattern.test(newCanonical)) {
          // Doesn't match expected pattern - remove and let code auto-generate
          shouldRemove = true;
          fileIssues.push(`Removed incorrect canonical pattern: ${oldCanonical}`);
        }
      }

      if (shouldRemove) {
        delete data.seo.canonical;
        stats.canonicalRemoved++;
        modified = true;
      } else if (shouldFix && newCanonical !== oldCanonical) {
        data.seo.canonical = newCanonical;
        stats.canonicalFixed++;
        modified = true;
      }
    }

    // 3. Remove auto-generated seo.title (let code generate)
    // Keep custom titles that don't match standard patterns
    if (data.seo?.title) {
      const isAutoGenerated =
        // Treatment patterns
        data.seo.title.includes('Uses, Side Effects, Dosage') ||
        data.seo.title.includes('Dosing, Black Box Warnings') ||
        // Condition patterns
        data.seo.title.includes('Symptoms, Causes, Treatment & Support') ||
        data.seo.title.includes('Symptoms, Treatment & Support') ||
        // Resource patterns
        data.seo.title.includes('Free Online') && data.seo.title.includes('Tool & Scoring Guide') ||
        data.seo.title.includes('Mental Health App Review & Features') ||
        data.seo.title.includes('24/7 Mental Health') ||
        // Generic pattern
        data.seo.title.endsWith('| HeyPsych') && data.seo.title.split(':').length <= 2;

      if (isAutoGenerated) {
        fileIssues.push('Removed auto-generated seo.title');
        delete data.seo.title;
        stats.titleRemoved++;
        modified = true;
      }
    }

    // 4. Remove auto-generated seo.description (selective)
    if (data.seo?.description) {
      const isAutoGenerated =
        data.seo.description.includes('comprehensive guide') ||
        data.seo.description.includes('is used to treat') ||
        data.seo.description.includes('Learn about') && data.seo.description.length < 100 ||
        data.seo.description.startsWith('Free online') && data.seo.description.includes('screening tool');

      // For resources, be more conservative - keep most descriptions
      const isResource = entityType === 'resource';

      if (isAutoGenerated && !isResource) {
        fileIssues.push('Removed auto-generated seo.description');
        delete data.seo.description;
        stats.descriptionRemoved++;
        modified = true;
      }
    }

    // 5. Ensure seo.no_index is set (default false)
    if (data.seo && data.seo.no_index === undefined) {
      data.seo.no_index = false;
      fileIssues.push('Added seo.no_index = false');
      stats.noIndexAdded++;
      modified = true;
    }

    // 6. Remove empty seo object
    if (data.seo && Object.keys(data.seo).length === 0) {
      delete data.seo;
      fileIssues.push('Removed empty seo object');
      modified = true;
    }

    // Write changes
    if (modified) {
      filesModified++;

      if (!DRY_RUN) {
        const newContent = JSON.stringify(data, null, 2) + '\n';
        fs.writeFileSync(filePath, newContent, 'utf-8');
      }

      issues.push({
        file: path.relative(process.cwd(), filePath),
        issues: fileIssues
      });
    }

    filesProcessed++;

  } catch (error) {
    console.error(`Error processing ${filePath}:`, error.message);
  }
}

/**
 * Recursively process all JSON files in a directory
 */
function processDirectory(dir, entityType, pathPrefix) {
  if (!fs.existsSync(dir)) {
    console.warn(`⚠️  Directory not found: ${dir}`);
    return;
  }

  const entries = fs.readdirSync(dir, { withFileTypes: true });

  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);

    if (entry.isDirectory()) {
      processDirectory(fullPath, entityType, pathPrefix);
    } else if (entry.isFile() && entry.name.endsWith('.json')) {
      fixEntityFile(fullPath, entityType, pathPrefix);
    }
  }
}

// Main execution
console.log('🔧 Fixing SEO issues across all entity types...\n');
console.log(`Mode: ${DRY_RUN ? 'DRY RUN (no files will be modified)' : 'LIVE (files will be updated)'}\n`);

// Process each entity type
ENTITY_DIRS.forEach(({ path: dir, type, pathPrefix }) => {
  const fullPath = path.join(process.cwd(), dir);
  console.log(`Processing ${type}s in ${dir}...`);
  processDirectory(fullPath, type, pathPrefix);
});

// Report results
console.log('\n📊 Summary:');
console.log(`   Files processed: ${filesProcessed}`);
console.log(`   Files modified: ${filesModified}`);
console.log('\n📈 Changes breakdown:');
console.log(`   Schema injection removed: ${stats.schemaInjectionRemoved}`);
console.log(`   Canonical URLs fixed: ${stats.canonicalFixed}`);
console.log(`   Canonical URLs removed: ${stats.canonicalRemoved}`);
console.log(`   Titles removed (auto-gen): ${stats.titleRemoved}`);
console.log(`   Descriptions removed (auto-gen): ${stats.descriptionRemoved}`);
console.log(`   no_index added: ${stats.noIndexAdded}`);

if (issues.length > 0 && issues.length <= 50) {
  console.log('\n📝 Changes made:');
  issues.forEach(({ file, issues: fileIssues }) => {
    console.log(`\n   ${file}:`);
    fileIssues.forEach(issue => {
      console.log(`      ✓ ${issue}`);
    });
  });
} else if (issues.length > 50) {
  console.log(`\n📝 ${issues.length} files modified (showing first 10):`);
  issues.slice(0, 10).forEach(({ file, issues: fileIssues }) => {
    console.log(`\n   ${file}:`);
    fileIssues.forEach(issue => {
      console.log(`      ✓ ${issue}`);
    });
  });
  console.log('\n   ... and ' + (issues.length - 10) + ' more files');
}

if (DRY_RUN) {
  console.log('\n⚠️  This was a dry run. No files were modified.');
  console.log('   Run without --dry-run to apply changes.');
} else {
  console.log('\n✅ All fixes applied successfully!');
}

console.log('\n📋 Next steps:');
console.log('   1. Review changes: git diff data/');
console.log('   2. Validate: node scripts/validate-all-entities-seo.cjs');
console.log('   3. Commit changes');
